import {
  PlaneGeometry,
  Mesh,
  NodeMaterial,
  texture,
  uv,
  positionLocal,
  normalLocal,
  mul,
  vec2,
  vec3,
  float,
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- Load textures ---
  const imageTexture = ctx.textureLoader.load(config.imageUrl);
  const depthTexture = config.depthMapUrl ? ctx.textureLoader.load(config.depthMapUrl) : null;

  // --- Geometry with tessellation ---
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // --- Material with displacement using TSL ---
  const material = new NodeMaterial();
  material.colorNode = texture(imageTexture, uv());

  if (depthTexture) {
    const depthNode = texture(depthTexture, uv()).r; // assume single channel depth
    const displacementAmount = float(0.05); // tune as needed
    material.displacementNode = mul(depthNode, displacementAmount);
  }

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.position.set(config.position?.x ?? -2.5, config.position?.y ?? -1.1, config.position?.z ?? 0);
  mesh.rotation.set(config.rotation?.x ?? 0, config.rotation?.y ?? 0, config.rotation?.z ?? 0);
  mesh.scale.set(config.scale?.x ?? 1, config.scale?.y ?? 1, config.scale?.z ?? 1);

  // --- Cinematic primitives ---
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](mesh, prim.params);
      }
    });
  }

  // --- User data handlers ---
  mesh.userData.handlers = {
    hover: () => {
      gsap.to(mesh.position, {
        y: mesh.position.y + 0.15,
        duration: 0.3,
        ease: 'power3.out',
      });
    },
    click: () => {
      // emit via some global event bus or callback? Assume config.onEvent
      if (config.onEvent) config.onEvent('hub-home.select');
    },
  };

  // --- Entrance animation: weighted-settle ---
  const entranceTimeline = gsap.timeline();
  entranceTimeline.from(mesh.scale, {
    x: 0,
    y: 0,
    z: 0,
    duration: 0.9,
    ease: 'power4.out',
    onComplete: () => {
      // weighted-settle overshoot
      gsap.to(mesh.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.2,
        ease: 'power2.out',
        onComplete: () => {
          gsap.to(mesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.3,
            ease: 'power4.out',
          });
        },
      });
    },
  });

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    entranceTimeline.kill();
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    if (depthTexture) depthTexture.dispose();
  };

  return mesh;
}
